pub fn property(c: char, mask: u16) -> bool {
    let number = u64::from(c as u32);
    let found = RANGES.partition_point(|entry| (*entry >> 16 & 0x1fffff) < number);
    RANGES.get(found).map_or(false, |entry| {
        (*entry >> 37) <= number && (*entry as u16 & mask) != 0
    })
}

pub fn altered(c: char, which: usize) -> String {
    let sought = c as u32;
    if let Ok(place) = CHANGES.binary_search_by_key(&sought, |row| row.0) {
        let row = &CHANGES[place];
        return match which { 0 => row.1, 1 => row.2, 2 => row.3, _ => row.4 }.to_owned();
    }
    String::from(c)
}

